  const [sessions,setSessions] = useState(['DEMO-SESSION-01','DEMO-SESSION-02']);
  const [consents,setConsents] = useState<ConsentEvent[]>([{id:'DEMO-CONSENT-01',purpose:'account',version:'DEMO-NOTICE-01',status:'accepted',time:'04 Oct 2026 · demo time'}]);
  const [modal,setModal] = useState<'erase'|'withdraw'|'mfa'|'draft'|null>(null);
  const [proof,setProof] = useState(false);
  const [erasureAgree,setErasureAgree] = useState(false);
  const mandatory = mandatoryMfa.includes(role);
  useEffect(()=>{if(mandatory)setMfaEnabled(true);},[mandatory]);
  function open(next:typeof modal) {setModal(next);setProof(false);setErasureAgree(false);}
  function exportOwnData() {downloadDemo('own-account-demo.json',{synthetic:true,notAProductionExport:true,profile:{display_name:savedName,email:'avery.demo@example.invalid',role,organisation:'Demo Lab A'},sessions,consents});notify(t('Your invented account data was downloaded.','ดาวน์โหลดข้อมูลบัญชีจำลองแล้ว'));}
